describe('Sauce Demo Store - Mobile Responsiveness', () => {
  it('should be usable on a small screen', () => {
    cy.viewport(375, 812); // Set viewport to mobile portrait

    // Visit the Sauce Demo store
    cy.visit('https://www.saucedemo.com');

    // Log in with standard_user / secret_sauce
    cy.get('#user-name').type('standard_user');
    cy.get('#password').type('secret_sauce');
    cy.get('#login-button').click();

    // Verify that the inventory page is shown
    cy.get('.inventory_list').should('be.visible');

    // Verify that the burger menu button is visible
    cy.get('#react-burger-menu-btn').should('be.visible');

    // Click the burger menu button to open the side menu
    cy.get('#react-burger-menu-btn').click();

    // Verify that the side menu container is open
    cy.get('.bm-menu').should('be.visible');

    // Verify that the logout link is visible inside the side menu
    cy.get('#logout_sidebar_link').should('be.visible');
  });
});
